defaultModel:
{{
  {
    "selectedId": "",
    "events": (() => {
     const allEvents = (Get_Calendar_Locations.data && Get_Calendar_Locations.data.length > 0) ? Get_Calendar_Locations.data : (appsmith.store.cache_calendrier || []);
      const selectedRaw = sel_filtre_machine_calendrier.selectedOptionValues || [];
      const selected = selectedRaw.map(v => String(v));

      // Test sécurisé du statut batterie (booléen ou texte "true")
      const estBatterie = (e) => e.Est_Sur_Batterie === true || String(e.Est_Sur_Batterie).toLowerCase() === 'true';

      // 1. Générateur de couleurs uniques par machine
      function genererCouleurUnique(index) {
        const hue = (index * 137.5) % 360;
        return `hsl(${Math.round(hue)}, 70%, 42%)`;
      }

      const mapCouleurs = {};
      const machinesUniques = Array.from(new Set(allEvents.map(e => String(e.ID_Machine_Location)))).sort();

      machinesUniques.forEach((idMachine, idx) => {
        mapCouleurs[idMachine] = genererCouleurUnique(idx);
      });

      // 2. Si aucune machine n'est filtrée : affichage normal de toutes les réservations
      if (selected.length === 0) {
        return allEvents.map(evt => {
          const idStr = String(evt.ID_Machine_Location);
          const couleur = mapCouleurs[idStr] || 'hsl(210, 70%, 42%)';
          return { ...evt, backgroundColor: couleur, borderColor: couleur };
        });
      }

      // 3. Vérification si au moins un matériel sélectionné est à batterie
      const auMoinsUnBatterieSelectionne = allEvents.some(e => 
        selected.includes(String(e.ID_Machine_Location)) && estBatterie(e)
      );

      const result = [];

      allEvents.forEach(evt => {
        const idStr = String(evt.ID_Machine_Location);
        const estSelectionne = selected.includes(idStr);

        if (estSelectionne) {
          // Machine sélectionnée : couleur dynamique dédiée
          const couleur = mapCouleurs[idStr] || 'hsl(210, 70%, 42%)';
          result.push({
            ...evt,
            backgroundColor: couleur,
            borderColor: couleur
          });
        } else if (auMoinsUnBatterieSelectionne && estBatterie(evt)) {
          // Autre machine à batterie non sélectionnée : affichage en GRIS
          result.push({
            ...evt,
            title: `🔋 [Autre batterie] ${evt.title}`,
            backgroundColor: '#64748b',
            borderColor: '#475569'
          });
        }
      });

      return result;
    })()
  }
}}

onEventClick:
{{
  (async function() {
    const locId = Custom1.model.selectedId;

    if (!locId) {
      showAlert("Identifiant de réservation non détecté au clic.", "warning");
      return;
    }

    // Mémorise la page pour le bouton retour
    await storeValue('page_precedente', '🔑 Location');

    // Ouvre la page Détail Location avec l'ID attendu par la requête
    await navigateTo('Détail Location', { id: locId });
  })()
}}

