let calendar = null;
appsmith.onReady(() => {
  const calendarEl = document.getElementById('calendar');
  calendar = new FullCalendar.Calendar(calendarEl, {
    initialView: 'timeGridWeek',
    locale: 'fr',
    firstDay: 1,
    // Démarre le lundi

    // Découpage Matin / Après-midi
    allDaySlot: false,
    slotMinTime: '08:00:00',
    slotMaxTime: '18:00:00',
    slotDuration: '05:00:00',
    expandRows: true,
    displayEventTime: false,
    slotLabelContent: function (arg) {
      return arg.date.getHours() < 13 ? 'Matin' : 'Après-midi';
    },
    headerToolbar: {
      left: 'prev,next today',
      center: 'title',
      right: 'dayGridMonth,timeGridWeek,listMonth'
    },
    buttonText: {
      today: "Aujourd'hui",
      month: 'Mois',
      week: 'Semaine',
      list: 'Liste'
    },
    // Chargement dynamique des événements
    events: function (info, successCallback, failureCallback) {
      const evts = appsmith.model && appsmith.model.events ? appsmith.model.events : [];
      successCallback(evts);
    },
    // 🟢 Clic sur une réservation
    eventClick: function (info) {
      // 1. Enregistre l'ID dans le modèle
      appsmith.updateModel({
        selectedId: info.event.id
      });

      // 2. Déclenche l'événement configuré dans Appsmith (onEventClick)
      setTimeout(function () {
        appsmith.triggerEvent("onEventClick");
      }, 100);
    }
  });
  calendar.render();
});

// Rechargement instantané au filtre
appsmith.onModelChange(model => {
  if (calendar) {
    calendar.refetchEvents();
  }
});

